content:
{
  "criteria": [
    {
      "kind": "inclusion",
      "text": "Histopathologically-confirmed diagnosis of cancer that is metastatic or unresectable at Screening.",
      "quote": "Histopathologically-confirmed diagnosis of cancer that is metastatic or unresectable at Screening."
    },
    {
      "kind": "inclusion",
      "text": "Subjects with metastatic or locally and/or regionally advanced unresectable CSCC.",
      "quote": "Subjects with metastatic or locally and/or regionally advanced unresectable CSCC."
    },
    {
      "kind": "inclusion",
      "text": "Cohort A1: Subjects who have not received prior systemic therapy for CSCC and who are not eligible for curative radiation.",
      "quote": "Cohort A1: Subjects who have not received prior systemic therapy for CSCC and who are not eligible for curative radiation."
    },
    {
      "kind": "inclusion",
      "text": "Cohort A2: Subjects who have progressed while receiving a PD-1–blocking antibody or within 12 weeks of discontinuation.",
      "quote": "Cohort A2: Subjects who have progressed while receiving a PD-1–blocking antibody or within 12 weeks of discontinuation."
    },
    {
      "kind": "inclusion",
      "text": "Subjects with metastatic or locally and/or regionally advanced unresectable MCC.",
      "quote": "Subjects with metastatic or locally and/or regionally advanced unresectable MCC."
    },
    {
      "kind": "inclusion",
      "text": "Cohort B1: Subjects who have not received prior systemic therapy for MCC.",
      "quote": "Cohort B1: Subjects who have not received prior systemic therapy for MCC."
    },
    {
      "kind": "inclusion",
      "text": "Cohort B2: Subjects who have progressed while receiving a PD-1–blocking antibody or within 12 weeks of discontinuation.",
      "quote": "Cohort B2: Subjects who have progressed while receiving a PD-1–blocking antibody or within 12 weeks of discontinuation."
    },
    {
      "kind": "inclusion",
      "text": "Cohorts C1 and C2: Previously treated subjects with advanced or metastatic TNBC must have disease that is HER2-negative, estrogen and progesterone receptor-negative, or < 5% expression based on ASCO/CAP guidelines.",
      "quote": "Cohorts C1 and C2: Previously treated subjects with advanced or metastatic TNBC must have disease that is HER2-negative, estrogen and progesterone receptor-negative, or < 5% expression based on American Society of Clinical Oncology/College of American Pathologists guidelines"
    },
    {
      "kind": "inclusion",
      "text": "Subjects with disease recurrence or progression following neoadjuvant or adjuvant therapy are eligible. Subjects with advanced or metastatic disease may have up to 5 lines of systemic therapy.",
      "quote": "Subjects with disease recurrence or progression following neoadjuvant or adjuvant therapy are eligible. Subjects with advanced or metastatic disease may have up to 5 lines of systemic therapy."
    },
    {
      "kind": "inclusion",
      "text": "Patients must have previously received treatment with sacituzumab govitecan (all TNBC patients), with trastuzumab deruxtecan (HER2-low patients) and with PARP inhibitor (for BRCA) patients.",
      "quote": "Patients must have previously received treatment with sacituzumab govitecan (all TNBC patients), with trastuzumab deruxtecan (HER2-low patients) and with PARP inhibitor (for BRCA) patients."
    },
    {
      "kind": "inclusion",
      "text": "Cohort C1: Subjects who have not received prior therapy with iCPIs.",
      "quote": "Cohort C1: Subjects who have not received prior therapy with iCPIs."
    },
    {
      "kind": "inclusion",
      "text": "Cohort C2: Subjects who have progressed while receiving a PD-1–blocking antibody or within 12 weeks of discontinuation.",
      "quote": "Cohort C2: Subjects who have progressed while receiving a PD-1–blocking antibody or within 12 weeks of discontinuation."
    },
    {
      "kind": "inclusion",
      "text": "Cohort D: Advanced BCC subjects (metastatic or locally advanced) who are not candidates for curative surgery and have not received prior therapy with a hedgehog pathway inhibitor (vismodegib or sonidegib) or prior anti-PD-1/PD-L1 therapy and who do not wish to receive or who are not candidates for a hedgehog inhibitor.",
      "quote": "Cohort D: Advanced BCC subjects (metastatic or locally advanced) who are not candidates for curative surgery and have not received prior therapy with a hedgehog pathway inhibitor (vismodegib or sonidegib) or prior anti-PD-1/PD-L1 therapy and who do not wish to receive or who are not candidates for a hedgehog inhibitor."
    },
    {
      "kind": "inclusion",
      "text": "Cohort E (not conducted in Europe): Advanced non-small cell lung cancer (NSCLC) subjects (locally advanced who are not candidates for surgical resection or definitive chemoradiation or metastatic) whose tumors have high PD-L1 expression (TPS ≥50%) based on a prior PD-L1 result as determined by a CAP/CLIA (or equivalently licensed) lab, with no EGFR, ALK or ROS1 aberrations, and who have not received prior anti-PD-1/PD-L1 therapy and are amenable to IT therapy and do not wish to receive chemotherapy.",
      "quote": "Cohort E (not conducted in Europe): Advanced non-small cell lung cancer (NSCLC) subjects (locally advanced who are not candidates for surgical resection or definitive chemoradiation or metastatic) whose tumors have high PD-L1 expression (TPS ≥50%) based on a prior PD-L1 result as determined by a CAP/CLIA (or equivalently licensed) lab, with no EGFR, ALK or ROS1 aberrations, and who have not received prior anti-PD-1/PD-L1 therapy and are amenable to IT therapy and do not wish to receive chemotherapy.",
      "thresholds": [
        {
          "test": "PD-L1 TPS",
          "op": ">=",
          "value": 50,
          "unit": "%"
        }
      ]
    },
    {
      "kind": "inclusion",
      "text": "Cohort F: R/M Oropharyngeal squamous cell carcinoma (OPSCC) subjects with PD-L1 CPS score ≥1, HPV-positive disease who have not received prior systemic therapy for R/M disease.",
      "quote": "Cohort F: R/M Oropharyngeal squamous cell carcinoma (OPSCC) subjects with PD-L1 CPS score ≥1, HPV-positive disease who have not received prior systemic therapy for R/M disease.",
      "thresholds": [
        {
          "test": "PD-L1 CPS",
          "op": ">=",
          "value": 1,
          "unit": null
        }
      ]
    },
    {
      "kind": "inclusion",
      "text": "Measurable disease, as defined by RECIST v1.1 and all of the following: At least 1 accessible lesion amenable to repeated IT injection.",
      "quote": "Measurable disease, as defined by RECIST v1.1 and all of the following: At least 1 accessible lesion amenable to repeated IT injection."
    },
    {
      "kind": "inclusion",
      "text": "A previously irradiated lesion may be used as a target lesion if subsequent disease progression in that lesion (at least 20% increase in dimensions with a 5 mm absolute increase) was documented.",
      "quote": "A previously irradiated lesion may be used as a target lesion if subsequent disease progression in that lesion (at least 20% increase in dimensions with a 5 mm absolute increase) was documented."
    },
    {
      "kind": "inclusion",
      "text": "Able to provide tissue from a core or excisional/incisional biopsy (fine needle aspirate is not sufficient). A newly obtained biopsy (within 90 days before the start of study treatment) is preferred but an archival sample is acceptable if no intervening therapy was received.",
      "quote": "Able to provide tissue from a core or excisional/incisional biopsy (fine needle aspirate is not sufficient). A newly obtained biopsy (within 90 days before the start of study treatment) is preferred but an archival sample is acceptable if no intervening therapy was received."
    },
    {
      "kind": "inclusion",
      "text": "Adequate organ function based on most recent laboratory values within 3 weeks before first dose of study treatment on W1D1: Bone marrow function: neutrophil count ≥ 1500/mm3, platelet count ≥ 100,000/mm3, hemoglobin concentration ≥ 9 g/dL.",
      "quote": "Adequate organ function based on most recent laboratory values within 3 weeks before first dose of study treatment on W1D1: Bone marrow function: neutrophil count ≥ 1500/mm3, platelet count ≥ 100,000/mm3, hemoglobin concentration ≥ 9 g/dL",
      "thresholds": [
        {
          "test": "neutrophil count",
          "op": ">=",
          "value": 1500,
          "unit": "/mm3"
        },
        {
          "test": "platelet count",
          "op": ">=",
          "value": 100000,
          "unit": "/mm3"
        },
        {
          "test": "hemoglobin",
          "op": ">=",
          "value": 9,
          "unit": "g/dL"
        }
      ]
    },
    {
      "kind": "inclusion",
      "text": "Liver function: total bilirubin ≤ 1.5 times the upper limit of normal (ULN) with the following exception: subjects with Gilbert Disease total serum bilirubin ≤ 3 times ULN; aspartate aminotransferase and alanine aminotransferase ≤ 3 times the ULN.",
      "quote": "Liver function: total bilirubin ≤ 1.5 times the upper limit of normal (ULN) with the following exception: subjects with Gilbert Disease total serum bilirubin ≤ 3 times ULN; aspartate aminotransferase and alanine aminotransferase ≤ 3 times the ULN",
      "thresholds": [
        {
          "test": "total bilirubin",
          "op": "<=",
          "value": 1.5,
          "unit": "x ULN"
        },
        {
          "test": "total serum bilirubin (Gilbert)",
          "op": "<=",
          "value": 3,
          "unit": "x ULN"
        },
        {
          "test": "AST",
          "op": "<=",
          "value": 3,
          "unit": "x ULN"
        },
        {
          "test": "ALT",
          "op": "<=",
          "value": 3,
          "unit": "x ULN"
        }
      ]
    },
    {
      "kind": "inclusion",
      "text": "Renal function: estimated (Cockcroft-Gault) or measured creatinine clearance ≥ 30 mL/min.",
      "quote": "Renal function: estimated (Cockcroft-Gault) or measured creatinine clearance ≥ 30 mL/min",
      "thresholds": [
        {
          "test": "creatinine clearance",
          "op": ">=",
          "value": 30,
          "unit": "mL/min"
        }
      ]
    },
    {
      "kind": "inclusion",
      "text": "Coagulation: International normalized ratio (INR) or prothrombin time (PT) ≤ 1.5 times ULN unless subject is receiving anticoagulant therapy, as long as PT or partial thromboplastin time (PTT) is within therapeutic range of intended use of anticoagulants.",
      "quote": "Coagulation: International normalized ratio (INR) or prothrombin time (PT) ≤ 1.5 times ULN unless subject is receiving anticoagulant therapy, as long as PT or partial thromboplastin time (PTT) is within therapeutic range of intended use of anticoagulants.",
      "thresholds": [
        {
          "test": "INR",
          "op": "<=",
          "value": 1.5,
          "unit": "x ULN"
        },
        {
          "test": "PT",
          "op": "<=",
          "value": 1.5,
          "unit": "x ULN"
        }
      ]
    },
    {
      "kind": "inclusion",
      "text": "Activated partial thromboplastin time or PTT ≤ 1.5 times ULN unless subject is receiving anticoagulant therapy, as long as PT or PTT is within therapeutic range of intended use of anticoagulants.",
      "quote": "Activated partial thromboplastin time or PTT ≤ 1.5 times ULN unless subject is receiving anticoagulant therapy, as long as PT or PTT is within therapeutic range of intended use of anticoagulants.",
      "thresholds": [
        {
          "test": "aPTT",
          "op": "<=",
          "value": 1.5,
          "unit": "x ULN"
        },
        {
          "test": "PTT",
          "op": "<=",
          "value": 1.5,
          "unit": "x ULN"
        }
      ]
    },
    {
      "kind": "inclusion",
      "text": "Age ≥ 18 years at time of consent.",
      "quote": "Age ≥ 18 years at time of consent.",
      "thresholds": [
        {
          "test": "age",
          "op": ">=",
          "value": 18,
          "unit": "years"
        }
      ]
    },
    {
      "kind": "inclusion",
      "text": "Eastern Cooperative Oncology Group (ECOG) Performance Status of 0 to 1 at Screening.",
      "quote": "Eastern Cooperative Oncology Group (ECOG) Performance Status of 0 to 1 at Screening."
    },
    {
      "kind": "inclusion",
      "text": "Capable of understanding and complying with protocol requirements.",
      "quote": "Capable of understanding and complying with protocol requirements."
    },
    {
      "kind": "inclusion",
      "text": "Able and willing to provide written informed consent and to follow study instructions. Subjects unable to provide written informed consent on their own behalf will not be eligible for the study.",
      "quote": "Able and willing to provide written informed consent and to follow study instructions. Subjects unable to provide written informed consent on their own behalf will not be eligible for the study."
    }
  ]
}
